//
// ValueUtils — generic presence checks (null / undefined). Was part of the old Validator.
//
export default class ValueUtils {
    /** True if `value` is `undefined`. */
    static isUndefined(value) { return value === undefined; }
    /** True if `value` is not `undefined`. */
    static notUndefined(value) { return value !== undefined; }
    /** True if `value` is `null`. */
    static isNull(value) { return value === null; }
    /** True if `value` is not `null`. */
    static notNull(value) { return value !== null; }
    static isValid(value) { return ValueUtils.notUndefined(value) && ValueUtils.notNull(value); }
}
